'use client';

import { AlertTriangle, Loader2 } from 'lucide-react';
import type { Route } from 'next';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { PasswordInput } from '@/components/ui/password-input';
import {
  describePasswordUpdateError,
  MIN_PASSWORD_LENGTH,
  validateNewPassword,
} from '@/lib/auth-errors';
import { createClient } from '@/lib/supabase/client';

/** Typed routes are regenerated by `next dev`/`next build`; the cast keeps typecheck independent of that. */
const FORGOT_PASSWORD_HREF = '/auth/forgot-password' as Route;

type Phase = 'checking' | 'ready' | 'invalid' | 'saving';

const FIELD_CLASS =
  'h-11 rounded-control border border-line bg-raised px-3 text-[16px] text-ink outline-none transition-colors placeholder:text-ink-4 focus-visible:border-accent-border focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-ring lg:h-9 lg:text-[13px]';

export function SetPasswordForm() {
  const router = useRouter();
  const [phase, setPhase] = useState<Phase>('checking');
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [error, setError] = useState<string | undefined>();

  // An invitation sent through the Supabase admin API uses the implicit flow: the session
  // arrives in the URL fragment, which the PKCE-configured client refuses to read. A reset
  // requested from the sign-in page arrives with a session cookie set by /auth/callback. Handle
  // both, and treat "no session" as an expired or already-used link.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const supabase = createClient();
      const fragment = new URLSearchParams(window.location.hash.replace(/^#/, ''));
      const accessToken = fragment.get('access_token');
      const refreshToken = fragment.get('refresh_token');
      const hadFragment = fragment.size > 0;

      if (accessToken && refreshToken) {
        await supabase.auth.setSession({
          access_token: accessToken,
          refresh_token: refreshToken,
        });
      }
      if (hadFragment) {
        // Tokens must not linger in the address bar or browser history.
        window.history.replaceState(null, '', window.location.pathname);
      }
      const { data } = await supabase.auth.getUser();
      if (!cancelled) setPhase(data.user ? 'ready' : 'invalid');
    })().catch(() => {
      if (!cancelled) setPhase('invalid');
    });
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const problem = validateNewPassword(password, confirmation);
    if (problem) {
      setError(problem);
      return;
    }
    setError(undefined);
    setPhase('saving');

    const supabase = createClient();
    const { error: updateError } = await supabase.auth.updateUser({ password });
    if (updateError) {
      setError(describePasswordUpdateError(updateError));
      setPhase(updateError.status === 401 || updateError.status === 403 ? 'invalid' : 'ready');
      return;
    }
    // Make the person sign in once with the new password: proves it was stored correctly.
    await supabase.auth.signOut();
    router.replace('/login?reset=1');
  }

  if (phase === 'checking') {
    return (
      <p className="flex items-center gap-2 text-[13px] text-ink-3" role="status">
        <Loader2 aria-hidden="true" className="size-4 animate-spin" /> Checking your link
      </p>
    );
  }

  if (phase === 'invalid') {
    return (
      <div role="alert" className="rounded-card border border-line bg-raised p-4">
        <AlertTriangle aria-hidden="true" className="size-5 text-negative" />
        <p className="mt-2 text-[13px] text-ink">This link has expired or was already used</p>
        <p className="mt-1 text-[12px] text-ink-3 leading-relaxed">
          Links work once and last one hour. Ask for a fresh one, or ask a NextX owner to invite
          you again.
        </p>
        <Button asChild variant="primary" size="lg" className="mt-4 w-full">
          <Link href={FORGOT_PASSWORD_HREF}>Request a new link</Link>
        </Button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-3">
      <div className="flex flex-col gap-1.5">
        <label
          htmlFor="new-password"
          className="text-[11px] text-ink-3 uppercase tracking-[0.08em]"
        >
          New password
        </label>
        <PasswordInput
          id="new-password"
          name="new-password"
          autoComplete="new-password"
          enterKeyHint="next"
          required
          minLength={MIN_PASSWORD_LENGTH}
          value={password}
          onChange={(event) => setPassword(event.target.value)}
          aria-describedby="new-password-hint"
          className={FIELD_CLASS}
        />
        <p id="new-password-hint" className="text-[11px] text-ink-4">
          At least {MIN_PASSWORD_LENGTH} characters.
        </p>
      </div>

      <div className="flex flex-col gap-1.5">
        <label
          htmlFor="confirm-password"
          className="text-[11px] text-ink-3 uppercase tracking-[0.08em]"
        >
          Repeat the password
        </label>
        <PasswordInput
          id="confirm-password"
          name="confirm-password"
          autoComplete="new-password"
          enterKeyHint="go"
          required
          value={confirmation}
          onChange={(event) => setConfirmation(event.target.value)}
          className={FIELD_CLASS}
        />
      </div>

      {error ? (
        <p className="text-[12px] text-negative" role="alert">
          {error}
        </p>
      ) : null}

      <Button
        type="submit"
        variant="primary"
        size="lg"
        disabled={phase === 'saving'}
        className="mt-1 w-full max-sm:h-12 max-sm:text-[15px]"
      >
        {phase === 'saving' ? (
          <>
            <Loader2 className="size-4 animate-spin" /> Saving
          </>
        ) : (
          'Save password'
        )}
      </Button>
    </form>
  );
}
